<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Merchant/index')}">商家列表</a>|					<a href="{pigcms{:U('Merchant/store',array('mer_id'=>$merchant['mer_id']))}" class="on">{pigcms{$merchant.name} - 店铺列表</a>|					<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Merchant/store_add',array('mer_id'=>$merchant['mer_id']))}','添加店铺',620,440,true,false,false,addbtn,'store_add',true);">添加店铺</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col><col><col><col><col><col><col width="180" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>店铺名称</th>								<if condition="!isset($config['not_o2o_demo'])">								<th>联系电话</th>								</if>								<th>最后编辑时间</th>								<th>平台点击数</th>								<if condition="$config['meal_alias_name']">									<th>{pigcms{$config.meal_alias_name}</th>								</if>								<if condition="$config['group_alias_name'] && $config['single_system_type'] neq 'village_group'">									<th>{pigcms{$config.group_alias_name}</th>								</if>								<if condition="$config['shop_alias_name']">									<th>{pigcms{$config.shop_alias_name}</th>								</if>								<if condition="$config['store_open_waimai']"><th>{pigcms{$config.waimai_alias_name}</th></if>                                <if condition="C('customization.internal_membership_card')">                                    <th>一卡通</th>                                </if>								<th>状态</th>                                <if condition="!empty($merchant['miaomaiyun_erp_appid']) && !empty($merchant['miaomaiyun_erp_appsecret'])">                                    <th>淼迈云商品同步</th>                                </if>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($store_list)">								<volist name="store_list" id="vo">									<tr>										<td>{pigcms{$vo.store_id}</td>										<td>{pigcms{$vo.name}</td>										<if condition="!isset($config['not_o2o_demo'])">										<td>{pigcms{$vo.phone}</td>										</if>										<td><if condition="$vo['last_time']">{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}<else/>无</if></td>										<td>{pigcms{$vo.hits}</td>										<if condition="$config['meal_alias_name']">											<td><if condition="$vo['have_meal'] eq 1"><font color="green">开启</font><else/><font color="red">关闭</font></if></td>										</if>										<if condition="$config['group_alias_name'] && $config['single_system_type'] neq 'village_group'">											<td><if condition="$vo['have_group'] eq 1"><font color="green">开启</font><else/><font color="red">关闭</font></if></td>										</if>										<if condition="$config['shop_alias_name']">											<td><if condition="$vo['have_shop'] eq 1"><font color="green">开启</font><else/><font color="red">关闭</font></if></td>										</if>										<if condition="$config['store_open_waimai']">											<td><if condition="$vo['have_waimai'] eq 1"><font color="green">开启</font><else/><font color="red">关闭</font></if></td>										</if>                                        <if condition="C('customization.internal_membership_card')">                                            <td>                                                <if condition="$vo['is_internal_card_pay'] eq 1">                                                    <font color="green">开启</font>                                                <else/>                                                    <font color="red">关闭</font>                                                </if>                                            </td>                                        </if>										<td><if condition="$vo['status'] eq 1"><font color="green">启用</font><elseif condition="$vo['status'] eq 2"/><font color="red">审核中</font><else/><font color="red">关闭</font></if></td>                                        <if condition="!empty($merchant['miaomaiyun_erp_appid']) && !empty($merchant['miaomaiyun_erp_appsecret'])">                                            <td>                                                <if condition="!empty($vo['miaomaiyun_erp_storeid'])">                                                <button type="button" onclick="goodsSync({pigcms{$vo['mer_id']},{pigcms{$vo['store_id']})">同步</button>                                                    <span id="{pigcms{$vo['store_id']}_sync"></span>                                                <else/>                                                    请先绑定淼迈云对应门店ID                                                </if>                                            </td>                                        </if>                                        <td class="textcenter"><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Merchant/store_edit',array('store_id'=>$vo['store_id'],'frame_show'=>true))}','查看店铺信息',620,440,true,false,false,false,'detail',true);">查看</a> | <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Merchant/store_edit',array('store_id'=>$vo['store_id']))}','编辑店铺信息',620,440,true,false,false,editbtn,'store_add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="store_id={pigcms{$vo.store_id}" url="{pigcms{:U('Merchant/store_del')}">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/><script>    function goodsSync(mer_id, store_id){        $.ajax({            type: "POST",            url: "{pigcms{:U('Merchant/miaoMaiGoodsSync')}",            data: {mer_id:mer_id, store_id:store_id},            dataType: "json",            success: function(data){                if(data.status == 0){                    laryer.msg(data.msg)                    return false;                }                var interval = setInterval(function() {                    $.ajax({                        url: "{pigcms{:U('Merchant/miaoMaiGoodsSync')}",                        method: 'POST',                        data: {mer_id:mer_id, store_id:store_id, get_percent:1},                        dataType: 'json',                        success: function(response) {                            $('#'+store_id+'_sync').html(response.msg);                            if(response.status == 2 || response.status == 0){                                clearInterval(interval)                            }                        },                        error: function(xhr, status, error) {                            // 请求失败时的处理逻辑                            console.error('Error:', error);                        }                    });                }, 1000);            }        });    }</script>